59ba5897-8c3c-46c0-89db-3f8181333f70	[{"id": "f7230bcb-af84-4337-b0f3-8afcf11ed513", "name": "Mon Paris", "brand": "Yves Saint Laurent", "score": 87, "reason": "Yves Saint Laurent Mon Paris suits the user for its floral and fruity composition enhanced by bergamot, aligning with their love for fruity and floral families.", "image_url": null, "top_notes": ["Strawberry", "Raspberry", "Saffron", "Bergamot"], "base_notes": ["Patchouli", "Vanilla", "Amber", "Musk"], "description": null, "heart_notes": ["Datura", "Peony", "Orange Blossom", "Jasmine"], "fragrance_family": ["Floral", "Fruity"]}, {"id": "d2850602-3ba2-4115-b1a5-7bc644fa899c", "name": "Oud Maracuja", "brand": "Maison Crivelli", "score": 84, "reason": "Maison Crivelli Oud Maracuja appeals to the user due to its woody and fruity profile with dominant bergamot notes, complementing their preferred scent families and notes.", "image_url": null, "top_notes": ["Passion Fruit", "Bergamot", "Pink Pepper"], "base_notes": ["Sandalwood", "Musk", "Amber"], "description": "A bold and exotic fusion of smoky oud and lush tropical passion fruit from the innovative French niche house Maison Crivelli. The fragrance balances the richness of Middle Eastern oud with the juicy, tangy vibrancy of maracuja (passion fruit). It is an adventurous and sensual composition that bridges East and West.", "heart_notes": ["Oud", "Rose", "Jasmine"], "fragrance_family": ["Woody", "Fruity", "Oriental"]}, {"id": "15415123-1e4e-4ccf-a4dc-877d3fcdd1d6", "name": "Fall Cashmere", "brand": "Skylar Clean Beauty", "score": 77, "reason": "Skylar Clean Beauty Fall Cashmere is ideal for the user with its woody and gourmand elements, catering to their inclination towards woody scents.", "image_url": null, "top_notes": ["Cardamom", "Saffron", "Black Pepper"], "base_notes": ["Sandalwood", "Musk", "Amber", "Vanilla"], "description": "A warm, cozy autumn fragrance with soft woody and gourmand notes, designed to evoke the feeling of cashmere and fall warmth. Part of Skylar's hypoallergenic, clean fragrance line.", "heart_notes": ["Cashmere Wood", "Iris", "Rose"], "fragrance_family": ["Woody", "Warm Spicy", "Gourmand"]}, {"id": "238cded4-9a04-464b-b051-9c46afc5cc8c", "name": "Love by Kilian", "brand": "By Kilian", "score": 74.5, "reason": "By Kilian Love by Kilian is a great match given its floral and gourmand blend with jasmine and bergamot, aligning with the user's note preferences.", "image_url": null, "top_notes": ["Neroli", "Bergamot", "Pink Pepper"], "base_notes": ["Vanilla", "White Musk", "Civet"], "description": "A gourmet floral blend that marries the sweetness of sugar and vanilla with the floral heart of orange blossom, creating a warm and sensual aura.", "heart_notes": ["Orange Blossom", "Jasmine", "Rose"], "fragrance_family": ["Floral", "Gourmand"]}, {"id": "610d9d3c-e8de-400b-ac41-13cc50aa3f27", "name": "Chanel No. 5", "brand": "Chanel", "score": 74, "reason": "Chanel Chanel No. 5 offers a classic floral composition with jasmine notes, appealing to the user's love for floral arrangements.", "image_url": null, "top_notes": ["Aldehydes", "Lemon", "Bergamot", "Neroli"], "base_notes": ["Sandalwood", "Vanilla", "Vetiver", "Musk", "Resinous Notes"], "description": null, "heart_notes": ["Jasmine", "Rose", "Lilac", "Iris"], "fragrance_family": ["Floral", "Aldehydic"]}, {"id": "088531aa-598d-4e4b-8809-e58c69732328", "name": "Bois du Portugal", "brand": "Creed", "score": 74, "reason": "Creed Bois du Portugal is perfect for the user as its woody and aromatic profile with bergamot, sandalwood, and amber aligns seamlessly with their taste in notes and families.", "image_url": null, "top_notes": ["Bergamot", "Lavender"], "base_notes": ["Amber", "Vanilla", "Musk"], "description": null, "heart_notes": ["Sandalwood", "Cypress"], "fragrance_family": ["Woody", "Aromatic"]}]	2026-05-24 17:09:56.584+00
